import assert from 'node:assert/strict';import {independentTreeRanks} from './legacy-2016-spring-fundamentals-oracle';
const attrs=(tag:string)=>Object.fromEntries([...tag.matchAll(/([\w-]+)="([^"]*)"/g)].map(m=>[m[1],m[2]]));const num=(a:Record<string,string>,name:string)=>{assert(name in a,name);const n=Number(a[name]);assert(Number.isFinite(n));return n;};const near=(a:number,b:number,tol=1e-6)=>assert(Math.abs(a-b)<=tol,`${a} != ${b}`);const decode=(s:string)=>s.replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&amp;','&').replaceAll('&quot;','"');
