 for(const[,path,inside]of nodes){assert(paths.includes(path));const circles=[...inside.matchAll(/<circle\b([^>]*)>/g)];assert.equal(circles.length,1);const a=attrs(circles[0][1]),x=num(a,'cx'),y=num(a,'cy'),r=num(a,'r');near(r,22);assert(x>=22&&x<=698&&y>=22&&y<=418);map[path]={x,y,r};near(y,45+path.length*82);const texts=[...inside.matchAll(/<text\b([^>]*)>(.*?)<\/text>/g)],wanted=path===''?String(ranks['']):path==='L'?String(ranks.L):path==='R'?'a':path==='RRL'?'b':'';assert.equal(texts.length,wanted?1:0,`label/blank ${path}`);if(wanted){const t=attrs(texts[0][1]);assert.equal(decode(texts[0][2]),wanted);near(num(t,'x'),x);near(num(t,'y'),y+8);}else blanks++;}
 assert.equal(blanks,6);assert.equal(Object.keys(map).length,10);const lines=[...svg.matchAll(/<line\b([^>]*)>/g)].map(m=>attrs(m[1]));assert.equal(lines.length,9);const children=new Set<string>();
 for(const e of lines){const from=e['data-from'],to=e['data-to'];assert.equal(from,to.slice(0,-1),'actual parent');assert(paths.includes(to)&&to!=='');assert(!children.has(to));children.add(to);const p=map[from],q=map[to],dx=q.x-p.x,dy=q.y-p.y,len=Math.hypot(dx,dy);assert(dy>0);assert(to.endsWith('L')?dx<0:dx>0,'left/right geometry');near(num(e,'x1'),p.x+dx*p.r/len);near(num(e,'y1'),p.y+dy*p.r/len);near(num(e,'x2'),q.x-dx*q.r/len);near(num(e,'y2'),q.y-dy*q.r/len);near(Math.hypot(num(e,'x1')-p.x,num(e,'y1')-p.y),p.r);near(Math.hypot(num(e,'x2')-q.x,num(e,'y2')-q.y),q.r);}
 for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=map[nodes[i][1]],b=map[nodes[j][1]];assert(Math.hypot(a.x-b.x,a.y-b.y)>=44);}
