 if(n===8){const[c,s]=v;edge('a1','M320 68 L320 112');edge('a2','M320 193 L320 238');edge('yes','M428 266 L580 266 L580 340');edge('no','M320 294 L320 339');edge('back','M320 420 L320 458 L152 458 L152 220 L320 220');assert.equal(Object.keys(edges).length,5);text('starttext','開始',320,54);text('q',`q←${c}`,320,146);text('r','r←x',320,178);text('cond','r < y',320,275);text('yeslabel','Yes',472,255);text('nolabel','No',352,322);text('end','終了',580,372);text('subtract','r←r-y',320,372);text('increment',`q←q+${s}`,320,404);const shape=svg.match(/<path data-shape="condition" d="([^"]+)"/);assert(shape);assert.equal(shape[1],'M320 238 L428 266 L320 294 L212 266 Z');assert(svg.includes('scope="col">qの値</th>')&&svg.includes('scope="col">rの値</th>'));assert.equal((svg.match(/<table>/g)||[]).length,1);assert.equal((svg.match(/<tr /g)||[]).length,4);assert.equal((svg.match(/<td>/g)||[]).length,8);assert(svg.includes('class="open-corner" aria-hidden="true"'));return {Yes:'right then end',No:'down',back:'condition entrance before initialization',table:'one shared q/r header and4 rows;8 cells'};}
 throw Error('unexpected diagram question');
